/**
 * Rich calculation result containing human display string, type kind,
 * raw scalar number (if applicable), and unit symbol (if applicable).
 */
public struct CalculationResult {
    public var display: String
    public var kind: ResultKind
    public var scalarValue: Double?
    public var unit: String?

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(display: String, kind: ResultKind, scalarValue: Double?, unit: String?) {
        self.display = display
        self.kind = kind
        self.scalarValue = scalarValue
        self.unit = unit
    }
}



extension CalculationResult: Equatable, Hashable {
    public static func ==(lhs: CalculationResult, rhs: CalculationResult) -> Bool {
        if lhs.display != rhs.display {
            return false
        }
        if lhs.kind != rhs.kind {
            return false
        }
        if lhs.scalarValue != rhs.scalarValue {
            return false
        }
        if lhs.unit != rhs.unit {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(display)
        hasher.combine(kind)
        hasher.combine(scalarValue)
        hasher.combine(unit)
    }
}


