/**
 * Error types emitted during Abacus evaluation or state manipulation.
 */
public enum AbacusFfiError {

    
    
    case UnknownUnit(String
    )
    case IncompatibleDimensions
    case IncompatibleFunctionArguments
    case AffineUnitOperation(String
    )
    case UnexpectedToken(String
    )
    case UnexpectedEnd
    case UnclosedParen
    case UnclosedBracket
    case IntervalInFunction
    case InvalidDate(String
    )
    case InvalidNumber(String
    )
    case IncompatibleOperatorType(String
    )
    case IncompatibleWithConversion(String
    )
    case RecursionLimitExceeded
    case ExponentLimitExceeded
    case UndefinedVariable(String
    )
    case EvaluationError(String
    )
    case CurrencyRateError(String
    )
    case LockError(String
    )
}


