    }
    if (uniffi_abacus_ffi_checksum_method_abacusengine_evaluate() != 65294) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_abacus_ffi_checksum_method_abacusengine_reset_variables() != 38469) {
